  [ [[v5748eaic9op2]] ] = { t = [[外装甲构装体]], q = [[外装甲构装体（第114页）：攻击如何以外装甲构装体为目标？我能获得它的抗力、免疫和其他防御吗？这一节里提到的“好处”和“阻碍”是什么？穿着它会影响速度吗？]], a = [=[外装甲构装体在AC方面视为[[胸甲]]。如果有东西以你为目标，它必须先命中你的AC。如果命中，这次攻击还必须穿透构装体的伤害减免或硬度，以及它的生命值。实际上，外装甲构装体的作用很像一池临时生命值：在构装体被摧毁之前，以你的AC为目标的攻击不会对你造成任何伤害。

绕过你AC的攻击会绕过这层保护，对你正常生效（这包括大多数范围效应）。如果构装体对某种攻击具有抗力或免疫，该攻击同样会绕过这层保护，对你正常生效。总的来说，外装甲构装体擅长减轻近战和远程攻击的伤害，但不会像你真的是那个构装体一样保护你。

例如，[[木魔像]]免疫寒冷并会被寒冷治疗；如果你穿着木魔像外装甲，用[[冰冻射线]]击中你不会伤害外装甲，只要攻击造成至少3点寒冷伤害还会治疗外装甲，并对你造成1d3点寒冷伤害。幸运的是，你不会获得构装体的弱点；木魔像对火焰有[[易伤]]，并不意味着你穿着木魔像外装甲时会受到150%的火焰伤害。

这一节里的“好处”，指外装甲构装体视为胸甲，以及它对近战和远程攻击的生命值缓冲。这一节里的“减值”，指外装甲构装体视为胸甲。

因为“视为胸甲”一段没有说它会影响你的速度（想必是因为构装体半活动，能帮助你移动），所以它不影响你的速度。

更新：第114页——在外装甲构装体改造中，第一段第二句，把“首先以构装体为目标”改为“伤害构装体”。第三句，把“重新获得所有阻碍”改为“保留所有阻碍”。]=], book = [[极限魔法]], date = [[2011/01/11]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fz#v5748eaic9op2]], cat = [[FAQ]], ai = false, pages = { [[外装甲构装体]] } },
  [ [[v5748eaic9rai]] ] = { t = [[混血术士与狂野血统]], q = [=[术士，[[混血术士]]和[[狂野血统]]：我能让同一个角色同时选择这两个变体职业吗？]=], a = [=[不能，因为变体职业规则说，没有任何替代职业能力可以取代或改变职业中与另一个替代职业能力相同的职业能力。混血术士和狂野血统这两个术士变体职业都改变了[[血统奥秘]]和血统力量，所以它们不是相容的变体职业。

请注意，GM当然有权允许这种组合。不过，该角色不应能用混血术士变体职业的能力，去选择已被狂野血统取代掉的较低等级血统力量。例如，一名狂野血统的残暴（深渊）术士在9级时用[[深渊之翼]]取代[[深渊强壮]]；该角色已经放弃深渊强壮，为狂野血统变体职业“付出了代价”，因此不能用混血术士的血统去选择深渊强壮作为她的15级或20级血统力量。]=], book = [[极限魔法]], date = [[2013/01/10]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fz#v5748eaic9rai]], cat = [[FAQ]], ai = false, pages = { [[混血术士]], [[狂野血统]] } },
  [ [[v5748eaic9sxm]] ] = { t = [[变体职业专有能力与专长]], q = [=[如果像狂野血统术士这样的变体职业授予了新的职业能力，比如血统力量、领域力量之类，那么没有该变体职业的我，能否用[[悠远血脉]]或[[信徒之赐]]这样的专长，选择该变体职业所授予的这些能力？]=], a = [=[不能。这些能力只存在于授予它们的变体职业。这一点尤其重要，因为在某些情况下，变体职业可能会放弃不对应的职业能力来换取这些能力。例如，狂野血统的[[精类血统|精类]]术士放弃了血统奥秘和1级能力，换取一个新的1级能力；而用专长获得1级能力的非术士，本来就没有血统奥秘。]=], book = [[极限魔法]], date = [[2015/01/02]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fz#v5748eaic9sxm]], cat = [[FAQ]], ai = false, pages = { [[悠远血脉]], [[信徒之赐]], [[狂野血统]] } },
}